          const isCalc = Boolean(document.getElementById("txtPantalla") || (name && name.startsWith("btn") && (/^[0-9]$/.test(caption) || ["+", "-", "*", "/", "×", "÷", "=", "C", "CE", "⌫", "C (Limpiar)", ".", "±", "M+", "M-", "MR", "MC", "%", "√x", "√", "x²", "1/x"].includes(caption))));

